#!/bin/bash
set -e
TOKEN=$(node -e "const a=JSON.parse(require('fs').readFileSync(process.env.HOME+'/.base44/auth/auth.json','utf8'));process.stdout.write(a.accessToken)")
echo "=== LIVE AGENT-CONFIGS ==="
curl -s -H "Authorization: Bearer $TOKEN" "https://app.base44.com/api/apps/6a9aedd33cd938f0f47b9ff7/agent-configs" | node -e "let s='';process.stdin.on('data',c=>s+=c).on('end',()=>{try{const d=JSON.parse(s);const items=d.items||[];console.log('total:',d.total??items.length);for(const a of items){console.log('---',a.name);console.log('  skills:',JSON.stringify(a.selected_skill_names));console.log('  memory:',JSON.stringify(a.memory_config&&{enabled:a.memory_config.enabled,scope:a.memory_config.scope}));console.log('  tools:',JSON.stringify((a.tool_configs||[]).map(t=>t.entity_name?('ent:'+t.entity_name+':'+t.allowed_operations.join('/')):('fn:'+t.function_name))));console.log('  whatsapp_greeting:',JSON.stringify(a.whatsapp_greeting),'telegram:',JSON.stringify(a.telegram_greeting))}}catch(e){console.log(s.slice(0,1000))}})"
